import{_ as e,j as a,k as i,a5 as n}from"./chunks/framework.3Z9w-w8R.js";const u=JSON.parse('{"title":"Advanced Molang","description":"Learn about more advanced topics within Molang.","frontmatter":{"title":"Advanced Molang","description":"Learn about more advanced topics within Molang.","mentions":["Ciosciaa","TheItsNameless","QuazChick"]},"headers":[{"level":2,"title":"Values","slug":"values","link":"#values","children":[{"level":3,"title":"Booleans","slug":"booleans","link":"#booleans","children":[]},{"level":3,"title":"Numbers","slug":"numbers","link":"#numbers","children":[]},{"level":3,"title":"Strings","slug":"strings","link":"#strings","children":[]}]},{"level":2,"title":"Operators","slug":"operators","link":"#operators","children":[]},{"level":2,"title":"Statements","slug":"statements","link":"#statements","children":[]},{"level":2,"title":"Collections","slug":"collections","link":"#collections","children":[]},{"level":2,"title":"Evaluation","slug":"evaluation","link":"#evaluation","children":[]},{"level":2,"title":"Limits","slug":"limits","link":"#limits","children":[]}],"relativePath":"documentation/advanced-molang.md","filePath":"documentation/advanced-molang.md"}'),o={name:"documentation/advanced-molang.md"};function l(t,s,c,d,r,p){return i(),a("div",null,s[0]||(s[0]=[n('<h2 id="values" tabindex="-1">Values <a class="header-anchor" href="#values" aria-label="Permalink to &quot;Values&quot;">​</a></h2><ul><li>All expressions in Molang return a value for the sake of checks against equality. Most expressions return <code class="shiki"><span>0</span></code>. Notably, assignments return the value assigned and loops return the resolved value of the looping statements, if one would exist.</li><li>All values in Molang are effectively single-precision floats.</li><li><code class="shiki"><span>this</span></code> is used to refer to the field&#39;s current value as it accumulated during evaluation. It is only observed to be usable in animations, but it may be usable elsewhere. As an example, if the accumulated transformations on the <code class="shiki"><span>x</span></code> <code class="shiki"><span>scale</span></code> of a bone would yield <code class="shiki"><span>62</span></code>, a final animation with a <code class="shiki"><span>x</span></code> <code class="shiki"><span>scale</span></code> of <code class="shiki"><span>-this</span></code> would resolve to <code class="shiki"><span>-62</span></code>, unsetting the prior transformations. This is used in vanilla animations in a number of places. Outside of animation contexts, <code class="shiki"><span>this</span></code> appears to always resolve to <code class="shiki"><span>0</span></code>.</li></ul><h3 id="booleans" tabindex="-1">Booleans <a class="header-anchor" href="#booleans" aria-label="Permalink to &quot;Booleans&quot;">​</a></h3><ul><li>Booleans are usable in Molang. <code class="shiki"><span>true</span></code> resolves to <code class="shiki"><span>1</span></code>, and <code class="shiki"><span>false</span></code> resolves to <code class="shiki"><span>0</span></code>.</li></ul><h3 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h3><ul><li>You can use leading <code class="shiki"><span>0</span></code>s in front of numbers, for example, to line them up better in your code.</li><li>Numbers can use exponential notation, such as <code class="shiki"><span>2.5e2</span></code>, which would be equal to 250. <code class="shiki"><span>e</span></code> can be suffixed with <code class="shiki"><span>+</span></code> or <code class="shiki"><span>-</span></code> to direct the power.</li><li>Numbers may be suffixed with a single <code class="shiki"><span>f</span></code>, often used to denote a floating point value. This can be found across vanilla code, but it is not believed to have any functionality.</li></ul><h3 id="strings" tabindex="-1">Strings <a class="header-anchor" href="#strings" aria-label="Permalink to &quot;Strings&quot;">​</a></h3><ul><li>Strings use <code class="shiki"><span>\\</span></code> (<code class="shiki"><span>\\\\</span></code> in escaped JSON) as some sort of escape or perhaps something else. It is unknown what functionality this has. It is known that the subsequent 2 characters are handed off to their own sub-parser, which does not exit correctly on a closing <code class="shiki"><span>&#39;</span></code>; this means the Molang string <code class="shiki"><span>&quot;v.type = &#39;\\\\x&#39;;&quot;</span></code> is invalid. <code class="shiki"><span>&#39;</span></code>, which is normally disallowed on its own as it would represent the end of the string, is allowed in the 2 characters following a <code class="shiki"><span>\\</span></code>.</li><li>String values are (mostly) incremental as they are represented against floats. It is possible to compare 2 individual character strings using equality or comparison operators or even to effectively &quot;adjust&quot; the contents of a single-character string. Multi-character behavior of such is unknown.</li></ul><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><p>The complete precedence list, from first to last evaluated:</p><ol><li><code class="shiki"><span>()</span></code> and <code class="shiki"><span>[]</span></code></li><li><code class="shiki"><span>-&gt;</span></code></li><li><code class="shiki"><span>!</span></code> and <code class="shiki"><span>-</span></code> (unary negation)</li><li><code class="shiki"><span>*</span></code> and <code class="shiki"><span>/</span></code></li><li><code class="shiki"><span>+</span></code> and <code class="shiki"><span>-</span></code> (binary subtraction)</li><li><code class="shiki"><span>&lt;</span></code>, <code class="shiki"><span>&lt;=</span></code>, <code class="shiki"><span>&gt;</span></code>, and <code class="shiki"><span>&gt;=</span></code></li><li><code class="shiki"><span>==</span></code> and <code class="shiki"><span>!=</span></code></li><li><code class="shiki"><span>&amp;&amp;</span></code></li><li><code class="shiki"><span>||</span></code></li><li><code class="shiki"><span>?</span></code> and <code class="shiki"><span>? :</span></code></li><li><code class="shiki"><span>??</span></code></li><li><code class="shiki"><span>=</span></code></li><li><code class="shiki"><span>return</span></code></li></ol><ul><li>Operators are considered from left to right for all operators except the conditionals.</li><li>Multiple <code class="shiki"><span>-&gt;</span></code> cannot be used in the same statement.</li><li>Logical operators short-circuit.</li></ul><h2 id="statements" tabindex="-1">Statements <a class="header-anchor" href="#statements" aria-label="Permalink to &quot;Statements&quot;">​</a></h2><ul><li>Assignments return the value assigned. You can therefore chain assignments if you need separate variables to work with from a single value, such as with <code class="shiki"><span>v.iterator_x = (v.iterator_z = math.random_integer(16, 32));</span></code>.</li><li>The last statement inside a brace scope does not need to end with a <code class="shiki"><span>;</span></code>.</li><li>Brace scopes can be used anywhere an expression can be used. <code class="shiki"><span>v.spawn_point ?? { v.target = false; };</span></code>, for example, would set <code class="shiki"><span>v.target</span></code> to <code class="shiki"><span>false</span></code> if <code class="shiki"><span>v.spawn_point</span></code> were not defined.</li></ul><h2 id="collections" tabindex="-1">Collections <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;Collections&quot;">​</a></h2><ul><li>The result of array subscripts cannot directly be an argument to <code class="shiki"><span>+</span></code>, <code class="shiki"><span>-</span></code>, <code class="shiki"><span>*</span></code>, or <code class="shiki"><span>/</span></code> but may still be used directly as function parameters (even math functions) or with other operators.</li></ul><h2 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h2><ul><li><code class="shiki"><span>initialize</span></code> and <code class="shiki"><span>pre_animation</span></code> are lazily concatenated. Molang strings in these arrays must be syntactically valid independently, but the basic concatenation of all independent strings must also be a valid Molang input.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Molang showed no reasonable limits to any language functionality, aside from numeric size. Loop counts, string lengths, Molang input length, collection size, etc., were observed to hold in very unreasonable situations.</li></ul>',20)]))}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
